    );
    assert_eq!(
        multi_value_tag_values(&["tool", "--tag=bogus", ""]),
        ["red", "blue", "green"]
    );
    assert_eq!(
        multi_value_tag_values(&["tool", "--tag", "bogus", "--limit", ""]),
        ["1", "2"]
    );
    assert_eq!(
