829	/// Whether a word can terminate a still-open multi-value option and start a
830	/// new argument instead, the way the parser would read it.
831	///
832	/// While an option still owes values, the parser greedily consumes every plain
833	/// word as one of its values; only flag-like words can switch to another
834	/// argument. An option that accepts hyphen values consumes those too.
835	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
836	    if arg.is_escape() {
837	        // `--` cancels every pending option unless its values may start with `--`.
838	        return !pending.is_allow_hyphen_values_set();
839	    }
840	    if !arg.to_value_os().starts_with("-") {
841	        // A plain word is always another value of the pending option.
842	        return false;
843	    }
844	    if pending.is_allow_hyphen_values_set() {
845	        return false;
846	    }
847	    // `-` is a stdio/value, not a flag.
848	    if arg.is_stdio() {
849	        return false;
850	    }
851	    // Both long and short flag styles can start a new argument; unknown flags
852	    // still switch (and error during parsing) rather than become option values.
853	    arg.to_long().is_some() || arg.to_short().is_some()
854	}
