+    for args in [&["tool", "r", ""][..], &["tool", "legacy-run", ""][..]] {
+        assert_eq!(
+            candidate_metadata(complete_subcommand_alias_tool(args)),
+            canonical,
+            "{args:?}"
+        );
+    }
+}
